var exitHtml = "";
function replace_f(f, r, s) {
    var ra = r instanceof Array, sa = s instanceof Array, l = (f = [].concat(f)).length, r = [].concat(r), i = (s = [].concat(s)).length;
    while (j = 0,i--)
        while (s[i] = s[i].split(f[j]).join(ra ? r[j] || "" : r[0]),++j < l);
    return sa ? s : s[0];
}

function ShowHide(Obj) {//ver 2.01+

    if (Obj.style.display == "none") {
        Obj.style.display = "";
    } else {
        Obj.style.display = "none";
    }
}

function corr_input(obj) {//ver 2.01+

    obj = obj.toLowerCase();

    obj = replace_f('ك', 'ک', obj);
    obj = replace_f('ي', 'ي', obj);
    obj = replace_f('¬', ' ', obj);
    obj = replace_f('ة', 'ه', obj);
    key = replace_f('‌', ' ', key);

    return obj;
}//func


